import base64
import ipaddress
import json
import re

encoded = "{{ '$normalize_alert.message.observables' | base64_encode }}"

try:
    raw = base64.b64decode(
        encoded, validate=True
    ).decode("utf-8")
    observables = json.loads(raw)

    if not isinstance(observables, list):
        observables = []
except (ValueError, TypeError, UnicodeError):
    observables = []

domain = ""

for item in observables:
    if isinstance(item, dict) and item.get("type") == "domain":
        domain = str(item.get("value", "")).strip().lower().rstrip(".")
        break

internal_suffixes = (
    ".local", ".lan", ".internal", ".home",
    ".home.arpa", ".localhost", ".test", ".invalid"
)

def validate_domain(value):
    if not value:
        return False, "missing"

    try:
        ipaddress.ip_address(value)
        return False, "ip_not_domain"
    except ValueError:
        pass

    if value == "localhost" or value.endswith(internal_suffixes):
        return False, "internal_domain"

    if len(value) > 253:
        return False, "invalid_domain"

    labels = value.split(".")

    if len(labels) < 2:
        return False, "invalid_domain"

    for label in labels:
        if not re.fullmatch(r"[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?", label):
            return False, "invalid_domain"

    if not re.search(r"[a-z]", labels[-1]):
        return False, "invalid_domain"

    return True, "valid_domain"

valid, reason = validate_domain(domain)

print(json.dumps({
    "valid": valid,
    "domain": domain if valid else "",
    "reason": reason
}))

