import base64
import json


def decode_response(template):
    try:
        return base64.b64decode(
            template, validate=True
        ).decode("utf-8").strip()
    except Exception:
        return ""


raw = decode_response(
    "{{ '$get_dshield.body' | base64_encode }}"
)

result = {
    "success": False,
    "source": "DShield",
    "ip": None,
    "score": None,
    "available": False,
    "matched": None,
    "error": None
}

try:
    if not raw:
        raise ValueError("Empty DShield response")

    obj = json.loads(raw)

    body = obj.get("body") or {}
    report = body.get("report") or {}
    full = report.get("full") or {}

    # Obsłuż także odpowiedź, w której report
    # znajduje się bezpośrednio w głównym obiekcie.
    if not full and isinstance(obj.get("report"), dict):
        report = obj.get("report") or {}
        full = report.get("full") or {}

    ip = full.get("ip")
    available = bool(ip and full)

    reputation = str(
        full.get("reputation") or ""
    ).strip().lower()

    try:
        maxrisk = int(full["maxrisk"]) if full.get("maxrisk") is not None else None
    except (ValueError, TypeError):
        maxrisk = None

    try:
        feeds = int(full["threatfeedscount"]) if full.get("threatfeedscount") is not None else None
    except (ValueError, TypeError):
        feeds = None

    reputation_points = (
        90 if reputation == "malicious"
        else 65 if reputation == "suspicious"
        else 0
    )

    risk_points = (
        25 if maxrisk is not None and maxrisk >= 4
        else 15 if maxrisk is not None and maxrisk >= 2
        else 5 if maxrisk == 1
        else 0
    )

    feed_points = (
        15 if feeds is not None and feeds >= 3
        else 8 if feeds is not None and feeds >= 1
        else 0
    )

    score = min(
        100,
        reputation_points + risk_points + feed_points
    ) if available else None

    result = {
        "success": available,
        "source": "DShield",
        "ip": ip,
        "score": score,
        "available": available,
        "matched": available if available else None,
        "count": full.get("count"),
        "attacks": full.get("attacks"),
        "maxrisk": maxrisk,
        "reputation": full.get("reputation"),
        "threatfeeds_count": feeds,
        "first_seen": full.get("firstseen"),
        "last_seen": full.get("lastseen"),
        "country_code": full.get("ascountry"),
        "as_name": full.get("asname"),
        "network": full.get("network"),
        "score_breakdown": {
            "reputation_points": reputation_points,
            "risk_points": risk_points,
            "feed_points": feed_points
        },
        "error": None if available else "DShield report has no usable IP record"
    }

except Exception as e:
    result["error"] = str(e)

print(json.dumps(result))

import json

raw = r'''$virustotal_lite'''

result = {
    "source": "VirusTotal",
    "analysis_status": "incomplete",
    "vt_score": None,
    "malicious": None,
    "suspicious": None,
    "undetected": None,
    "harmless": None,
    "total_engines": None,
    "sha256": "",
    "md5": "",
    "meaningful_name": "",
    "reputation": None,
    "error": None
}

try:
    response = json.loads(raw)

    # Odpowiedz powinna byc obiektem JSON
    if isinstance(response, list):
        if not response:
            raise ValueError("Empty VirusTotal response list")
        response = response[0]

    if not isinstance(response, dict):
        raise ValueError("VirusTotal response is not a JSON object")

    status = response.get("status")
    body = response.get("body", {})

    if not isinstance(body, dict):
        body = {}

    # Obsluga bledow HTTP, np. 404 NotFoundError
    if status and int(status) != 200:
        error_obj = body.get("error", {})
        error_message = (
            error_obj.get("message", "VirusTotal HTTP error")
            if isinstance(error_obj, dict)
            else str(error_obj)
        )
        result["error"] = {
            "http_status": status,
            "message": error_message
        }
    else:
        data = body.get("data", {})

        if isinstance(data, list):
            data = data[0] if data else {}

        if not isinstance(data, dict):
            data = {}

        attributes = data.get("attributes", {})
        if not isinstance(attributes, dict):
            attributes = {}

        stats = attributes.get("last_analysis_stats", {})
        if not isinstance(stats, dict):
            stats = {}

        malicious = int(stats.get("malicious", 0) or 0)
        suspicious = int(stats.get("suspicious", 0) or 0)
        undetected = int(stats.get("undetected", 0) or 0)
        harmless = int(stats.get("harmless", 0) or 0)

        total = malicious + suspicious + undetected + harmless

        if total > 0:
            result.update({
                "analysis_status": "complete",
                "vt_score": round(
                    100 * (malicious + suspicious) / total
                ),
                "malicious": malicious,
                "suspicious": suspicious,
                "undetected": undetected,
                "harmless": harmless,
                "total_engines": total,
                "sha256": attributes.get("sha256", ""),
                "md5": attributes.get("md5", ""),
                "meaningful_name": attributes.get("meaningful_name", ""),
                "reputation": int(attributes.get("reputation", 0) or 0)
            })
        else:
            result["error"] = "No usable analysis statistics in response"

except Exception as e:
    result["error"] = str(e)

print(json.dumps(result))

