import base64
import json
import re
from datetime import datetime, timezone


def decode_input(template):
    try:
        return base64.b64decode(
            template, validate=True
        ).decode("utf-8")
    except Exception:
        return ""


def as_dict(value):
    return value if isinstance(value, dict) else {}


def normalize_timestamp(value):
    if not value:
        return None

    try:
        value = str(value).strip()

        if value.endswith("Z"):
            value = value[:-1] + "+00:00"
        elif (
            len(value) >= 5
            and value[-5] in ("+", "-")
            and value[-4:].isdigit()
        ):
            # Konwertuj +0000 na +00:00
            value = value[:-5] + value[-5:-2] + ":" + value[-2:]

        parsed = datetime.fromisoformat(value)

        # Nie zakladamy strefy czasowej, jesli jej brakuje.
        if parsed.tzinfo is None:
            return None

        return (
            parsed.astimezone(timezone.utc)
            .isoformat(timespec="milliseconds")
            .replace("+00:00", "Z")
        )

    except (ValueError, TypeError, OverflowError):
        return None


# Odczyt surowego alertu z poprzedniego wezla.
raw = decode_input("{{ '$exec' | base64_encode }}")

try:
    alert = json.loads(raw)
except (ValueError, TypeError):
    alert = {}

alert = as_dict(alert)

rule = as_dict(alert.get("rule"))
agent = as_dict(alert.get("agent"))
data = as_dict(alert.get("data"))

win = as_dict(data.get("win"))
eventdata = as_dict(win.get("eventdata"))

# Timestamp ISO 8601 UTC.
timestamp = normalize_timestamp(alert.get("timestamp"))

# Poziom Wazuh.
try:
    level = int(rule.get("level"))
except (ValueError, TypeError):
    level = None

# Wspolna skala severity: 1 (low) - 5 (critical).
if level is None:
    severity = None
elif level >= 12:
    severity = 5
elif level >= 10:
    severity = 4
elif level >= 7:
    severity = 3
elif level >= 4:
    severity = 2
else:
    severity = 1

observables = []

# IP
srcip = data.get("srcip")

if isinstance(srcip, str) and srcip.strip():
    observables.append({
        "type": "ip",
        "value": srcip.strip()
    })

# Domena
domain = data.get("domain")

if not domain:
    dns = as_dict(data.get("dns"))
    question = as_dict(dns.get("question"))
    domain = question.get("name")

if isinstance(domain, str) and domain.strip():
    observables.append({
        "type": "domain",
        "value": domain.strip().rstrip(".").lower()
    })

# Hashe Sysmon: MD5, SHA1, SHA256, SHA512.
hashes_value = eventdata.get("hashes", "")

expected_lengths = {
    "md5": 32,
    "sha1": 40,
    "sha256": 64,
    "sha512": 128
}

if isinstance(hashes_value, str):
    for item in hashes_value.replace(";", ",").split(","):
        if "=" not in item:
            continue

        algorithm, value = item.split("=", 1)
        algorithm = (
            algorithm.strip().lower().replace("-", "")
        )
        value = value.strip().lower()

        if algorithm not in expected_lengths:
            continue

        if len(value) != expected_lengths[algorithm]:
            continue

        if not re.fullmatch(r"[0-9a-f]+", value):
            continue

        observables.append({
            "type": "hash",
            "algorithm": algorithm,
            "value": value
        })

# Uzytkownik
user = eventdata.get("user") or data.get("srcuser")

# Grupy/reguly alertu.
groups = rule.get("groups") or []

if not isinstance(groups, list):
    groups = [str(groups)]

normalized = {
    "source": "wazuh",
    "timestamp": timestamp,
    "hostname": agent.get("name"),
    "agent_id": agent.get("id"),
    "source_alert_id": alert.get("id"),
    "rule_id": rule.get("id"),
    "alert_type": groups,
    "severity": severity,
    "severity_source": "wazuh_level",
    "wazuh_level": level,
    "description": rule.get("description") or "",
    "ip": [
        item["value"]
        for item in observables
        if item["type"] == "ip"
    ],
    "user": user,
    "observables": observables,
    "original_alert": alert
}

print(json.dumps(normalized, ensure_ascii=False))

import ast
import base64
import json

encoded = "{{ '$incident' | base64_encode }}"

def parse_value(value):
    if isinstance(value, (dict, list)):
        return value
    if not isinstance(value, str):
        return value

    text = value.strip()
    if not text:
        return None

    try:
        return json.loads(text)
    except (json.JSONDecodeError, TypeError):
        try:
            return ast.literal_eval(text)
        except (ValueError, SyntaxError, TypeError):
            return value

try:
    raw = base64.b64decode(encoded, validate=True).decode("utf-8").strip()
    response = parse_value(raw)
except Exception:
    response = None

successful_ids = set()

def collect_successful_ids(value):
    value = parse_value(value)

    if isinstance(value, list):
        for item in value:
            collect_successful_ids(item)
        return

    if not isinstance(value, dict):
        return

    body = parse_value(value.get("body"))
    if str(value.get("status", "")).strip() == "201" and isinstance(body, dict):
        alert_id = body.get("_id")
        if isinstance(alert_id, str) and alert_id.strip():
            successful_ids.add(alert_id.strip())

    for item in value.values():
        if isinstance(item, (dict, list, str)):
            collect_successful_ids(item)

collect_successful_ids(response)

if len(successful_ids) == 1:
    result = {
        "valid": True,
        "alert_id": next(iter(successful_ids)),
        "reason": "ok"
    }
elif not successful_ids:
    result = {
        "valid": False,
        "alert_id": None,
        "reason": "no_successful_alert_id"
    }
else:
    result = {
        "valid": False,
        "alert_id": None,
        "reason": "multiple_successful_alert_ids"
    }

print(json.dumps(result))
